"""Source register and inspected-passage cache. Rebuild without network access."""
ASOF = '2026-10-28'
sources, retrievals = [], []
def src(n,title,author,url,date,kind,locator,passage,note='',status='Passage inspected',origin=None,method='web.run passage inspection'):
    sid=f'S{n:03d}'
    sources.append({'Source ID':sid,'Title':title,'Author / institution':author,'Publication date':date,'URL':url,'Access date':ASOF,'Source class':kind,'Primary / secondary':'Primary' if kind in ('Official record','Court record','Legislation','Primary statement','Official election return') else 'Secondary','Access status':status,'Origin ID':origin or sid,'Locator':locator,'Reliability / limitation':note or 'Supports the identified passage; implementation and individual causation require separate evidence.'})
    retrievals.append({'id':f'R{n:03d}','source_id':sid,'url_or_query':url,'access_date':ASOF,'route':'Canonical record, institutional mirror or identified reproduction','access_status':status,'origin_id':origin or sid,'locator':locator,'passage_paraphrase':passage,'method':method,'result':'Relevant passage inspected' if status=='Passage inspected' else note,'next_action':'Use only within the inspected scope; unresolved questions are in Research Queue.'})

src(1,'Shri Rajiv Gandhi: former Prime Minister','Prime Minister’s Office','https://www.pmindia.gov.in/en/former_pm/%E0%A4%B6%E0%A5%8D%E0%A4%B0%E0%A5%80-%E0%A4%B0%E0%A4%BE%E0%A4%9C%E0%A5%80%E0%A4%B5-%E0%A4%97%E0%A4%BE%E0%A4%82%E0%A4%A7%E0%A5%80/',None,'Official record','Profile, birth/education/entry paragraphs and tenure heading','Born 20 August 1944 in Bombay; Feroze and Indira Gandhi’s son and Nehru’s grandson. Studied at Doon, Cambridge and Imperial College, worked as an Indian Airlines pilot, married Sonia in 1968. Entered politics after Sanjay’s death; organised for the 1982 Asian Games and became a party general secretary. PM 31 October 1984–2 December 1989, aged 40 at entry.','Commemorative and favourable. Attendance is not proof of a degree. Its 401/508 election figure is rejected in favour of ECI. Party-presidency chronology is compressed.')
src(2,'Rajiv Gandhi: Members Bioprofile','Lok Sabha Secretariat','https://sansad.in/getFile/lsapps/MemberProfile/biodata_1_12/2731.htm?source=lsapps',None,'Official record','Positions held; election and death footnote','Lists election in 1981, 1984, 1989 and 1991; footnote says he died 21 May 1991 before results. Opposition leader 18 December 1989–24 December 1990. Lists Defence, Finance and other additional portfolios; Bharat Ratna posthumously in 1991.','Profile’s 19 October 1984 PM start is erroneous; PMO date used. Compressed portfolio table needs appointment notifications for exact boundaries. No tenth-Lok-Sabha service inferred.')
src(3,'Dhartipakar Madan Lal Agarwal v Rajiv Gandhi','Supreme Court of India','https://api.sci.gov.in/jonew/judis/8690.pdf','1987-05-11','Court record','PDF p.8 election facts; opening headnote and procedural account','Amethi by-election polled 14 June 1981; Rajiv declared elected 15 June with 258,884 votes. Petitioner received 2,728. Election petition failed for defective pleadings/material particulars.','Petitioner’s votes are not the runner-up total. Dismissal of a deficient petition does not adjudicate every political accusation.')
src(4,'General Elections 1984, volume I','Election Commission of India, Internet Archive copy','https://web.archive.org/web/20140718184911id_/http://eci.nic.in/eci_main/StatisticalReports/LS_1984/Vol_I_LS_84.pdf','1984','Official election return','PDF pp.81, 215–216; printed pp.78, 212–213','INC won 404 of 514 reported seats. Amethi: Rajiv 365,041; Maneka Gandhi 50,163; valid votes 436,263; electors 740,782; voters 446,289.','Archived official report recovered by curl and inspected with pypdf; not an independent dataset. INC label preserved. December returns do not include later Punjab/Assam polling.',method='curl download; pypdf extraction and page-specific inspection')
src(5,'General Elections 1989, volume I','Election Commission of India, Internet Archive copy','https://web.archive.org/web/20140718183934id_/http://eci.nic.in/eci_main/StatisticalReports/LS_1989/Vol_I_LS_89.pdf','1989','Official election return','PDF pp.88 and 265; printed pp.85 and 262','INC won 197 of 529 reported seats. Amethi: Rajiv 271,407; Raj Mohan Gandhi (JD) 69,269; valid votes 402,500; electors 910,177; voters 425,746.','Archived ECI original; constituency victory and national government loss are different outcomes.',method='curl download; pypdf extraction and page-specific inspection')
src(6,'General Elections 1991, volume I','Election Commission of India, Internet Archive copy','https://web.archive.org/web/20140718183558id_/http://eci.nic.in/eci_main/StatisticalReports/LS_1991/VOL_I_91.pdf','1991','Official election return','PDF pp.58 and 280; printed pp.55 and 277','INC won 232 of 521 reported seats. Amethi: Rajiv 187,138; Ravindra Pratap (BJP) 75,053; valid votes 351,548; electors 918,257; voters 376,202.','1991 win declared after his death; does not establish membership service or personal leadership of the ensuing government.',method='curl download; pypdf extraction and page-specific inspection')
src(7,'Rajiv Gandhi, the youngest Prime Minister with the largest mandate','Harikishan Sharma, Indian Express','https://indianexpress.com/article/political-pulse/rajiv-gandhi-youngest-prime-minister-largest-mandate-7932411/','2022-05-23','Journalism','Career and election paragraphs','MP oath 17 August 1981; PM succession after Indira’s assassination; Congress’s 1984 majority and 1989 defeat; Rajiv’s 1991 result was declared after his death.','Retrospective; primary returns supersede shorthand national-election descriptions.')
src(8,'C-DOT timeline','Centre for Development of Telematics','https://www.cdot.in/cdotweb/web/view_timeline.php?lang=en',None,'Official record','1984–1988 entries','Established 25 August 1984; Sam Pitroda adviser in 1985; first 128-line rural exchange at Kittur on 22 July 1986; MAX exchange in January 1988 and RAX-a-day programme in April 1988.','C-DOT predates Rajiv’s premiership. Institutional milestones are not proof of exclusive personal authorship or all later telecom growth.')
src(9,'Constitution (Fifty-second Amendment) Act, 1985','Gazette of India; Bombay High Court mirror','https://bombayhighcourt.gov.in/bhc/libweb/misc/coi/constitution/act/ACT/C052Act.pdf','1985-02-15','Legislation','PDF pp.1–3; sections 1–6 and Tenth Schedule paragraph 2','Assent 15 February 1985. Added Tenth Schedule disqualification for party defection and specified voting against party directions.','Original enactment; later amendments and judicial interpretation are distinct. Assent and commencement are not conflated.')
src(10,'Constitution (Sixty-first Amendment) Act, 1988','Gazette of India; Bombay High Court mirror','https://bombayhighcourt.gov.in/bhc/libweb/misc/coi/constitution/act/ACT/C061Act.pdf','1989-03-28','Legislation','Both pages; assent and article 326 substitution','Act titled 1988 received assent 28 March 1989 and substituted eighteen for twenty-one in article 326.','Distinguishes title year from enactment date.')
src(11,'Expenditure Budget 2011–12: School Education and Literacy','Government of India','https://www.indiabudget.gov.in/budget2011-2012/ub2011-12/eb/sbe58.pdf','2011','Official record','PDF p.7, printed p.201, item 15','Navodaya Vidyalaya Samiti scheme launched in 1986 to provide modern residential education for talented children predominantly from rural areas, under NPE 1986 as modified in 1992.','Later institutional account. 2011 school counts are not Rajiv-era outputs.')
src(12,'National Policy on Education 1986, Part IV','Government of India; Wikisource transcription','https://en.wikisource.org/wiki/National_Policy_on_Education_(1986)/Part_4','1986 / modified 1992','Primary statement','Paragraphs 4.1–4.3','Education policy seeks removal of disparities, women’s empowerment through curricula/training, literacy and retention, and access to technical and non-traditional occupations.','Composite text includes later modifications elsewhere. Used for stated equality orientation, not every clause as unchanged 1986 wording or achieved outcomes.')
src(13,'IGNOU: About us','Indira Gandhi National Open University','https://www.ignou.ac.in/pages/20',None,'Official record','Opening paragraphs','Established by an Act of Parliament in 1985; first two diploma programmes began in 1987 with 4,528 students.','Institutional history; today’s enrolment is not assigned to Rajiv’s tenure.')
src(14,'Mahila Samakhya','Poornima Chikarmane, INFLIBNET educational module','https://ebooks.inflibnet.ac.in/aep01/chapter/mahila-samakhya/',None,'Academic','Sections 4–7, origins and organisation','Formulated through consultation with officials, educationists and women’s groups in 1988; pilot in ten districts of UP, Karnataka and Gujarat in 1988–89. Women’s sanghas are central to the collective educational approach.','Interpretive educational account; separates formulation from rollout. Later expansion and all empowerment effects are not credited personally to Rajiv.')
src(15,'Politics in India since Independence: Regional Aspirations','NCERT','https://ncert.nic.in/textbook/pdf/leps207.pdf','2026–27 reprint','Academic','PDF pp.12,14,16–18,21; printed pp.123,125,127–129,132','Punjab accord in July 1985 offered Chandigarh, boundary and water arrangements, but violence persisted. Rajiv steered Mizo negotiations to settlement in 1986. Assam accord followed AASU talks in 1985; immigration remained contentious.','Textbook synthesis, not treaty original. Its description of Rajiv signing the Mizo accord is political shorthand and not used for formal signatories. Contemporary 1980s conditions distinguished from current reprint.',method='curl download; pypdf extraction; relevant pages inspected')
src(16,'Remna Ni 2026 message','Governor of Mizoram','https://rajbhavan.mizoram.gov.in/message-of-honble-governor-general-dr-vijay-kumar-singh-pvsm-avsm-ysm-retd-on-the-occasion-of-remna-ni-2026/','2026-06-29','Primary statement','English message, opening three paragraphs','Dates accord to 30 June 1986; celebrates sustained peace and credits political leaders, civil society, churches and communities.','Commemorative evaluation, not an independent causal study or evidence Rajiv was a formal signatory.')
src(17,'Full text: Indo-Sri Lanka agreement 1987','Sri Lanka Brief, reproduction of bilateral agreement','https://srilankabrief.org/full-text-of-the-indo-sri-lanka-agreement-1987/','1987-07-29','Primary statement','Agreement heading and clauses 1–2','Agreement between Rajiv Gandhi and J.R. Jayewardene set out territorial unity, ethnic recognition, provincial arrangements and disarmament commitments.','Treaty reproduction; MEA original inaccessible. Design and promises do not establish successful peace or voluntary acceptance by all armed parties.')
src(18,'Sri Lanka: A human rights briefing','Amnesty International, ASA 37/20/90','https://www.amnesty.org/en/wp-content/uploads/2021/06/asa370201990en.pdf','1990-09','Investigation','PDF pp.17–20, IPKF abuses and Valvettitturai','Documents allegations of disappearances, unlawful killings, torture and detention involving IPKF, including an alleged reprisal at Valvettitturai in August 1989.','Human-rights investigation; allegations and witness material are not judicial convictions or evidence of a personal instruction by Rajiv.')
src(19,'Prime Minister Rajiv Gandhi’s visit to China','Ministry of Foreign Affairs, China','https://www.mfa.gov.cn/eng/zy/wjls/3604_665547/202405/t20240531_11367553.html','2024 archive publication','Official record','Visit and joint communiqué paragraphs','Visit 19–23 December 1988; talks with Deng Xiaoping and Li Peng; boundary joint working group and wider cooperation alongside unresolved border differences.','Chinese institutional standpoint. Diplomatic process, not settlement of the boundary.')
src(20,'UN General Assembly A/S-15/PV.14: Rajiv Gandhi address','United Nations; NTI mirror','https://media.nti.org/pdfs/Gandhi_1988.pdf','1988-06-15','Primary statement','Meeting 9 June 1988; PDF pp.10–12','Rajiv proposed staged elimination of nuclear arms by 2010, participation by nuclear states and a UN-centred security framework.','Provisional verbatim record published 15 June; speech delivered 9 June. Proposal is not an adopted treaty or achieved disarmament.')
src(21,'India–Pakistan Non-Attack Agreement','Nuclear Threat Initiative','https://www.nti.org/education-center/treaties-and-regimes/india-pakistan-non-attack-agreement/',None,'Academic','Signature, entry into force and provisions','Signed 31 December 1988, entered into force 1 January 1991; prohibits attacks on nuclear facilities and requires exchange of location information.','Archived project no longer updated after April 2026; used only for stable historical dates and design.')
src(22,'Operation Cactus: India’s First Rapid Reaction Strategic Mission in the Neighbourhood','Gulbin Sultana, Journal of Defence Studies 17(4)','https://idsa.in/wp-content/uploads/2024/04/jds-17-4-Gulbin-Sultana.pdf','2023','Academic','PDF pp.4–5, Gayoom appeal and Rajiv statement','Maldives requested Indian help against the November 1988 coup attempt; Rajiv justified intervention through regional stability. Contrasts successful Cactus mission with the difficulties of IPKF.','Security-studies interpretation, not a universal judgement on Indian regional policy.')
src(23,'Nanavati Commission report, volume I','Commission of Inquiry; Delhi High Court mirror','https://www.delhihighcourt.nic.in/web/sites/default/files/reports/nanavati-i_eng_0.pdf','2005','Official record','PDF pp.182–184, concluding discussion','Finds organised anti-Sikh attacks, police failures and involvement of local Congress figures. Did not find evidence that Rajiv or other high-ranking leaders organised attacks; records his peace appeal and emergency actions.','Commission findings, not a criminal trial. Limited personal finding does not remove executive or political accountability questions; individual accused cases require separate current dockets.')
src(24,'India: No justice for 1984 anti-Sikh bloodshed','Human Rights Watch','https://www.hrw.org/news/2014/10/29/india-no-justice-1984-anti-sikh-bloodshed','2014-10-29','Investigation','Account of attacks, Rajiv speech and justice failures','Describes killings, sexual violence, impunity and Rajiv’s tree-falling metaphor after the attacks; criticises the long failure of accountability.','Advocacy report and 2014 snapshot. Not a current count of convictions or proof Rajiv ordered violence.')
src(25,'Kartongen Kemi Och Forvaltning AB v State through CBI','Delhi High Court; Indian Kanoon','https://indiankanoon.org/doc/561739/','2004-02-04','Court record','Paragraphs 77–79, 90–91 and 140–141','Court found no evidence of bribery against deceased public servants Rajiv Gandhi and S.K. Bhatnagar, removed related corruption-conspiracy charges, but retained distinct charges against others at that stage. Records Rajiv’s denial in Parliament.','Use judicial conclusions, not advocates’ submissions. Not a trial acquittal of Rajiv; 2004 order is not the end of every Bofors proceeding.')
src(26,'Supreme Court dismisses final Bofors appeal','Ashish Kumar Bhargava, NDTV','https://www.ndtv.com/india-news/last-shot-fired-in-bofors-legal-battle-supreme-court-dismisses-final-appeal-11876411','2026-08-06','Journalism','Reporter text, paragraphs below AI quick-read, lines 199–219','Reports dismissal of Ajay K. Agrawal’s appeal against the 2005 High Court quashing involving Hindujas/Bofors; notes earlier CBI appeal dismissal in 2018 for delay.','Original 2026 order not obtained. Reported procedural update, not a new merits acquittal of Rajiv or independently verified universal closure of all related matters.')
src(27,'Danial Latifi v Union of India','Supreme Court of India; Cornell mirror','https://www.law.cornell.edu/sites/www.law.cornell.edu/files/women-and-justice/Danial%20Latifi%20v.%20UOI%202001%20India.pdf','2001-09-28','Court record','Opening history and PDF pp.14–15 conclusions','1986 Muslim Women Act followed Shah Bano. Court upheld validity while requiring fair provision for a divorced wife’s future beyond iddat, made within iddat; maintenance liability not confined to iddat.','Historical legal interpretation, not personalised legal advice or a claim covering every subsequent maintenance judgment.')
src(28,'Congress after Indira: excerpt on Rajiv’s religious politics','Zoya Hasan, book excerpt in Scroll','https://scroll.in/article/941140/','2019-10-21','Academic','Discussion of Shah Bano, Ayodhya and 1989 campaign','Hasan interprets concessions around Muslim personal law and Ayodhya as compromising Congress secularism; discusses permission for shilanyas and Ram Rajya campaign rhetoric.','Attributed scholarly criticism. Narrative has a sequencing inconsistency around November 1989; not used for exact sequence or a direct PM order to unlock the mosque.')
src(29,'Congress and the Ram temple: a history of shifting positions','Shyamlal Yadav, Indian Express','https://indianexpress.com/article/explained/explained-politics/congress-ram-mandir-ayodhya-flip-flop-9108154/','2024-01-15','Journalism','1986 court-unlocking paragraphs','Local court ordered unlocking on 1 February 1986; government and party politics surrounding the decision became contested.','Distinguishes judicial order from political responsibility; direct Rajiv instruction is not established in this research.')
src(30,'Anti-defamation law: Rajiv Gandhi’s failed attempt','Express Web Desk, Indian Express','https://indianexpress.com/article/research/fake-news-order-smriti-irani-narendra-modi-anti-defamation-rajiv-gandhi-press-freedom-5121884/','2018-04-03','Journalism','Main article, lines 60–74','1988 bill passed Lok Sabha and was withdrawn after journalist, public and internal Congress resistance. Rajiv defended it, then affirmed press freedom at withdrawal.','Critical retrospective. Article’s July introduction date is not adopted; legislative text and exact introduction/withdrawal days remain uncollected.')
src(31,'73rd and 74th Amendments and women’s reservation','Khadija Khan, Indian Express','https://indianexpress.com/article/explained/explained-law/73-74-amendment-reservation-women-elected-bodies-8947255/lite/','2023-09-22','Journalism','Background paragraph and enactment chronology, lines 75–89','Rajiv’s 64th Amendment Bill failed in Rajya Sabha in 1989. The 73rd/74th amendments passed under P.V. Narasimha Rao in December 1992 and came into force in 1993.','Do not transfer later one-third quota or the exact later institutional design to the uninspected 1989 bill.')
src(32,'Union of India v Union Carbide Corporation','Supreme Court of India; Indian Kanoon','https://indiankanoon.org/doc/31860805/','2023-03-14','Court record','Paragraphs 1–5 and conclusion paragraph 51','Recounts December 1984 disaster and court-approved $470 million settlement in February 1989; later review left civil settlement while criminal proceedings were revived. Dismisses 2023 curative petitions.','Civil compensation procedure and criminal responsibility are distinct. No finding that Rajiv personally ordered Warren Anderson’s departure is established here.')
src(33,'Everyone Lives in Fear: Kashmir background','Human Rights Watch','https://www.hrw.org/reports/2006/india0906/3.htm','2006-09-11','Investigation','Political history, paragraphs on 1986–1989','Rajiv–Farooq agreement in 1986 preceded NC–Congress alliance; records credible allegations of rigging and arrests in 1987 and links disillusionment to subsequent militancy.','Attributed historical/rights assessment, not a criminal finding against Rajiv. No single-cause explanation of insurgency; 1990 events belong to successor governments.')
src(34,'24 years ago, another snooping case shaped history','Seema Chishti, Indian Express','https://indianexpress.com/article/india/india-others/24-yrs-ago-another-snooping-case-that-shaped-history/','2015-03-15','Journalism','Main narrative, lines 21–31','Congress supported Chandra Shekhar’s minority government, then withdrew after the March 1991 surveillance dispute. Chandra Shekhar announced resignation 6 March. Government described the police presence as routine and offered a probe.','Report includes attributed and disputed explanations. No conclusive finding of a personal surveillance order or one motive for withdrawal.')
src(35,'S. Shanmugadivelu, S. Nalini and others v State','Supreme Court, D.P. Wadhwa opinion; Indian Kanoon','https://indiankanoon.org/doc/1185147/','1999-05-11','Court record','Opening account of assassination and prosecution','Rajiv killed on 21 May 1991 by LTTE suicide bomber Dhanu during election campaigning; trial and appeals addressed a wider conspiracy.','Separate judicial opinion; used for common historical facts, not treated as the full bench’s unanimous sentencing disposition.')
src(36,'Supreme Court releases remaining six assassination convicts','Ananthakrishnan G, Indian Express','https://indianexpress.com/article/india/rajiv-gandhi-assassination-case-supreme-court-orders-release-of-convicts-8262532/','2022-11-12','Journalism','Opening report and order discussion, lines 20–39','On 11 November 2022 Court ordered premature release of remaining six following Perarivalan’s May release; considered long custody and conduct. Assassination occurred at Sriperumbudur.','Premature release is not reversal of conviction. Full order and later related proceedings uncollected.')
src(37,'India in the 1980s and 1990s: A Triumph of Reforms','Arvind Panagariya, IMF working paper WP/04/43','https://www.imf.org/external/pubs/ft/wp/2004/wp0443.pdf','2004-03','Academic','Summary/conclusions, PDF pp.2 and 7–8','Argues partial liberalisation during the 1980s helped growth but fiscal expansion and borrowing made the growth pattern fragile; differentiates later systemic reforms.','Author’s argument, not IMF institutional endorsement or an estimate of Rajiv’s personal causal contribution.',method='curl download; pypdf extraction; summary and conclusions inspected')
src(38,'From Hindu Growth to Productivity Surge','Dani Rodrik and Arvind Subramanian, IMF WP/04/77','https://www.imf.org/external/pubs/ft/wp/2004/wp0477.pdf','2004-05','Academic','PDF pp.28–29 and conclusions','Proposes an earlier pro-business shift beginning under Indira, gathering momentum under Rajiv; distinguishes incumbent-friendly changes from pro-competition reforms.','Competing economic explanation based on historical/econometric analysis; not a consensus or an exclusive leader attribution.',method='curl download; pypdf extraction; explanation and conclusion inspected')
src(39,'Annual Report 2013–2014: historical governments','Ministry of Parliamentary Affairs','https://www.mpa.gov.in/sites/default/files/AR13-14.pdf','2014','Official record','PDF pp.18–19, seventh to tenth Lok Sabha government table','Separates Rajiv ministry 31 October–31 December 1984 and period 31 December 1984–2 December 1989; ninth Lok Sabha dissolved 13 March 1991; successor Rao government began June 1991.','Historical administrative table, not appointment gazette. Party labels elsewhere in the retrospective table are anachronistic; only relevant dates used.')
src(40,'Rajiv elected Congress president','United Press International','https://www.upi.com/Archives/1984/11/12/Prime-Minister-Rajiv-Gandhi-was-unanimously-elected-president-of/9789469083600/','1984-11-12','Journalism','Search excerpt only; full article returned 403','Search excerpt reports election as party president on 12 November 1984.','Unreviewed chronology lead; full page inaccessible. Resolve appointment, election and 1985 centenary distinctions before assigning an exact day.','Search excerpt only')
src(41,'Consumer Protection Act 1986: metadata','India Code, Rajasthan collection','https://www.indiacode.nic.in/indiacode/handle/123456789/18554?view_type=browse','1986-12-24','Legislation','Search excerpt only','Metadata identifies enactment on 24 December 1986 and consumer councils/dispute redress.','Full page and earlier statutory PDF timed out; exact provisions and implementation unreviewed. Collection labels it STATE though the underlying central Act needs inspection.','Search excerpt only')
src(42,'Jawahar Rozgar Yojana: audit chapter','Comptroller and Auditor General of India','https://cag.gov.in/uploads/old_reports/union/union_compliance/2000/Civil/2000_book3/chapter3.pdf','2000','Official record','Search excerpt only','Excerpt describes merger of NREP and RLEGP into JRY in April 1989.','PDF returned 404; Yojana 1991 mirror timed out. No audit findings or measured employment outcomes treated as inspected.','Search excerpt only')
src(43,'Total Literacy Campaigns under National Literacy Mission, part I','Vandana Chakrabarti, INFLIBNET','https://ebooks.inflibnet.ac.in/aep01/chapter/total-literacy-campaigns-under-national-literacy-mission-part-i/',None,'Academic','Section 4, lines 157–163; Ernakulam section','Rajiv launched National Literacy Mission on 5 May 1988. Discusses limits of a technology-centred approach and the role of voluntary campaigns; Ernakulam programme involved state/district leadership.','Educational synthesis; targets are not achievements. Does not assign subsequent national literacy change solely to Rajiv.')

